def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= 500:
                rich_aggressive += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opponents:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = supply <= 17
    abundant = supply >= 22
    critical_me = hp <= 3 or no_water_days >= 1
    very_critical = hp <= 2 or no_water_days >= 2

    if very_critical:
        target = max(72.0, highest_prev + 3.0)
        if scarcity:
            target = max(target, 95.0)
        return min(budget, target)

    if critical_me:
        target = max(58.0, avg_prev + 4.0)
        if highest_prev >= 120:
            target = max(target, 82.0)
        if scarcity:
            target += 10.0
        return min(budget, target)

    if scarcity:
        if highest_prev >= 140:
            return min(budget, 28.0)
        target = max(46.0, avg_prev + 2.5)
        if desperate_count >= 2:
            target += 8.0
        return min(budget, target)

    if abundant:
        if highest_prev >= 120:
            return min(budget, 16.0)
        return min(budget, 22.0 + 2.0 * desperate_count)

    target = 32.0
    if highest_prev > 0:
        if highest_prev >= 130:
            target = 20.0
        elif highest_prev >= 90:
            target = 27.0
        else:
            target = max(32.0, avg_prev * 0.75)

    if rich_aggressive >= 2:
        target -= 4.0
    if day >= 8 and hp >= 6 and no_water_days == 0:
        target -= 3.0

    if target < 12.0:
        target = 12.0

    return min(budget, target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents and their yesterday bids
    alive_opps = []
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            if prev and prev.get('bid') is not None:
                try:
                    yesterday_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    # If no opponents alive, bid minimally to stay solvent
    if not alive_opps:
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.4))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Estimate how aggressive the field was yesterday
    if yesterday_bids:
        top_bid = max(yesterday_bids)
        second_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else top_bid
    else:
        top_bid = 0.0
        second_bid = 0.0

    # Supply pressure: higher supply reduces need to overpay
    # Map supply to a multiplier between ~0.85 (low supply) and ~0.55 (high supply)
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    t = max(0.0, min(1.0, float(t)))
    supply_mult = 0.85 - 0.30 * t

    # HP/no-water urgency
    urgency = 0.0
    if my_hp <= 2.0:
        urgency += 1.0
    elif my_hp <= 4.0:
        urgency += 0.6
    if no_water_days >= 2:
        urgency += 0.5
    if no_water_days >= 3:
        urgency += 0.4

    # Target bid heuristic: try to outbid safety bidders without matching their maximum
    # If top yesterday bid was very high, set target near it but slightly below/around.
    # Otherwise, anchor around second highest plus a small increment.
    if top_bid >= DAILY_SALARY * 1.25:
        target = top_bid * (0.92 - 0.08 * urgency)
    else:
        target = (second_bid + 2.0) * (0.90 - 0.10 * urgency) + (top_bid * 0.05)

    # Add urgency floor/ceiling relative to salary
    if urgency >= 1.0:
        target = max(target, DAILY_SALARY * 0.95)
    elif urgency >= 0.6:
        target = max(target, DAILY_SALARY * 0.75)
    else:
        target = max(target, DAILY_SALARY * 0.55)

    # If supply is high, reduce bid
    target *= supply_mult

    # Ensure we don't bid more than budget or absurdly high
    max_reasonable = my_budget
    if my_budget <= 0.0:
        return 0.0

    # Keep some budget buffer: don't spend all unless very urgent
    spend_frac = 0.65 if urgency >= 1.0 else (0.45 if urgency >= 0.6 else 0.35)
    cap = my_budget * spend_frac

    bid = min(target, cap, my_budget)
    if bid < 0.0:
        bid = 0.0
    return float(bid)
